create extension if not exists pgcrypto;
create table if not exists professionals (id uuid primary key references auth.users(id) on delete cascade, name text not null, council text, registration text, specialty text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid references auth.users(id), deleted_at timestamptz);
create table if not exists patients (id uuid primary key default gen_random_uuid(), professional_id uuid not null references auth.users(id), payload jsonb not null default '{}'::jsonb, version bigint not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid references auth.users(id), deleted_at timestamptz);
create table if not exists wounds (id uuid primary key default gen_random_uuid(), patient_id uuid not null references patients(id), professional_id uuid not null references auth.users(id), payload jsonb not null default '{}'::jsonb, version bigint not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid references auth.users(id), deleted_at timestamptz);
create table if not exists visits (id uuid primary key default gen_random_uuid(), patient_id uuid not null references patients(id), wound_id uuid not null references wounds(id), professional_id uuid not null references auth.users(id), payload jsonb not null default '{}'::jsonb, version bigint not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid references auth.users(id), deleted_at timestamptz);
create table if not exists reports (id uuid primary key default gen_random_uuid(), visit_id uuid not null references visits(id), patient_id uuid not null references patients(id), professional_id uuid not null references auth.users(id), payload jsonb not null default '{}'::jsonb, version bigint not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid references auth.users(id), deleted_at timestamptz);
create table if not exists record_access_log (id bigint generated always as identity primary key, professional_id uuid references auth.users(id), subject_patient_id uuid references patients(id), action text not null, created_at timestamptz not null default now());
alter table professionals enable row level security; alter table patients enable row level security; alter table wounds enable row level security; alter table visits enable row level security; alter table reports enable row level security; alter table record_access_log enable row level security;
create or replace function private.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;
do $$ declare t text; begin foreach t in array array['professionals','patients','wounds','visits','reports'] loop execute format('drop trigger if exists %I_touch on %I; create trigger %I_touch before update on %I for each row execute function private.touch_updated_at()', t, t, t, t); end loop; end $$;
create or replace function public.save_record(p_kind text, p_id uuid, p_payload jsonb, p_version bigint, p_base_version bigint) returns jsonb language plpgsql security invoker as $$ declare uid uuid := auth.uid(); result jsonb; begin if uid is null then raise exception 'not authenticated'; end if; if p_kind not in ('profiles','patients','wounds','visits','reports') then raise exception 'unsupported record kind'; end if; if p_kind='patients' then insert into patients(id, professional_id, payload, version, created_by) values(p_id,uid,p_payload,p_version,uid) on conflict(id) do update set payload=excluded.payload,version=excluded.version,updated_at=now() where patients.professional_id=uid and patients.version=p_base_version returning jsonb_build_object('kind',p_kind,'id',id,'payload',payload,'version',version) into result; elsif p_kind='wounds' then insert into wounds(id,patient_id,professional_id,payload,version,created_by) values(p_id,(p_payload->>'patientId')::uuid,uid,p_payload,p_version,uid) on conflict(id) do update set payload=excluded.payload,version=excluded.version,updated_at=now() where wounds.professional_id=uid and wounds.version=p_base_version returning jsonb_build_object('kind',p_kind,'id',id,'payload',payload,'version',version) into result; elsif p_kind='visits' then insert into visits(id,patient_id,wound_id,professional_id,payload,version,created_by) values(p_id,(p_payload->>'patientId')::uuid,(p_payload->>'woundId')::uuid,uid,p_payload,p_version,uid) on conflict(id) do update set payload=excluded.payload,version=excluded.version,updated_at=now() where visits.professional_id=uid and visits.version=p_base_version returning jsonb_build_object('kind',p_kind,'id',id,'payload',payload,'version',version) into result; elsif p_kind='reports' then insert into reports(id,visit_id,patient_id,professional_id,payload,version,created_by) values(p_id,(p_payload->>'visitId')::uuid,(p_payload->>'patientId')::uuid,uid,p_payload,p_version,uid) on conflict(id) do update set payload=excluded.payload,version=excluded.version,updated_at=now() where reports.professional_id=uid and reports.version=p_base_version returning jsonb_build_object('kind',p_kind,'id',id,'payload',payload,'version',version) into result; else insert into professionals(id,name,council,registration,specialty,created_by) values(uid,coalesce(p_payload->>'name',''),p_payload->>'council',p_payload->>'registration',p_payload->>'specialty',uid) on conflict(id) do update set name=coalesce(p_payload->>'name',''),council=p_payload->>'council',registration=p_payload->>'registration',specialty=p_payload->>'specialty',updated_at=now() returning jsonb_build_object('kind',p_kind,'id',id,'payload',p_payload,'version',1) into result; end if; if result is null then raise exception 'version conflict'; end if; return result; end $$;
create or replace function public.pull_records() returns table(kind text,id uuid,payload jsonb,version bigint) language sql security invoker as $$ select 'profiles',id,jsonb_build_object('id',id,'name',name,'council',council,'registration',registration,'specialty',specialty),1 from professionals where id=auth.uid() and deleted_at is null union all select 'patients',id,payload,version from patients where professional_id=auth.uid() and deleted_at is null union all select 'wounds',id,payload,version from wounds where professional_id=auth.uid() and deleted_at is null union all select 'visits',id,payload,version from visits where professional_id=auth.uid() and deleted_at is null union all select 'reports',id,payload,version from reports where professional_id=auth.uid() and deleted_at is null $$;
create policy "professionals own" on professionals for all using (id=auth.uid()) with check (id=auth.uid()); create policy "patients own" on patients for all using (professional_id=auth.uid()) with check (professional_id=auth.uid()); create policy "wounds own" on wounds for all using (professional_id=auth.uid()) with check (professional_id=auth.uid()); create policy "visits own" on visits for all using (professional_id=auth.uid()) with check (professional_id=auth.uid()); create policy "reports own" on reports for all using (professional_id=auth.uid()) with check (professional_id=auth.uid()); create policy "access own" on record_access_log for insert with check (professional_id=auth.uid());
insert into storage.buckets(id,name,public) values('clinical-photos','clinical-photos',false) on conflict(id) do nothing;
create policy "clinical photos own" on storage.objects for all using (bucket_id='clinical-photos' and (storage.foldername(name))[1]=auth.uid()::text) with check (bucket_id='clinical-photos' and (storage.foldername(name))[1]=auth.uid()::text);
